DROP VIEW IF EXISTS public.project_investment_summary;
ALTER TABLE public.projects ALTER COLUMN investment_target TYPE bigint;
ALTER TABLE public.projects ALTER COLUMN break_even TYPE bigint;
CREATE VIEW public.project_investment_summary AS SELECT p.id AS project_id, p.title, p.investment_target, COALESCE(sum(i.amount), 0::bigint) AS total_raised, count(i.id) AS total_investors FROM projects p LEFT JOIN investments i ON p.id = i.project_id AND i.payment_status::text = 'paid'::text GROUP BY p.id, p.title, p.investment_target;
UPDATE public.projects SET investment_target=10000000000, break_even=0, revenue_share=NULL, roi_estimate=NULL, financial_capex='[{"item": "Pháp lý, đăng ký, bảo hộ IP, nhãn hiệu", "note": "Giai đoạn 1 — Nền móng", "amount": 100000000, "depreciation_years": 0}, {"item": "Thuê đất/rừng 200–300 ha (đặt cọc + 2 năm đầu)", "note": "BQL Rừng phòng hộ Kon Rẫy · chi trả ≥1% doanh thu/năm", "amount": 1000000000, "depreciation_years": 0}, {"item": "Khởi chạy mảng Check-in & F&B", "note": "Ưu tiên tạo dòng tiền sớm", "amount": 2000000000, "depreciation_years": 5}, {"item": "Triển khai nền tảng Tech & AI Agent", "note": "Nền tảng quản trị vận hành + AI Agent", "amount": 1500000000, "depreciation_years": 5}, {"item": "Thiết kế tổng thể + quy hoạch chi tiết 1/500", "note": "Hồ sơ thiết kế và quy hoạch", "amount": 500000000, "depreciation_years": 0}, {"item": "Đội ngũ cốt lõi 12 tháng đầu", "note": "Nhân sự giai đoạn khởi động", "amount": 800000000, "depreciation_years": 0}, {"item": "Dự phòng vốn lưu động", "note": "Dự phòng", "amount": 500000000, "depreciation_years": 0}]'::jsonb, financial_opex='[]'::jsonb, revenue_phases='[]'::jsonb, cashflow='[]'::jsonb, financial_summary='{"total_capex": 6400000000, "von_dieu_le": 10000000000, "tien_mat_gop_giai_doan_dau": 6400000000, "dien_tich_ha": "200–300", "nguon": "Bản FINAL v5 — Cấu trúc doanh nghiệp tổng thể NOOI (04/10/2026)"}'::jsonb, updated_at=now() WHERE id='44b1faf9-5d03-4aee-8b5c-42bdfb41d8c7';
SELECT investment_target, break_even, revenue_share, roi_estimate, jsonb_array_length(financial_capex) AS capex_items, financial_opex, financial_summary FROM public.projects;
SELECT project_id, title, investment_target, total_raised FROM public.project_investment_summary;
